begin;
delete from profiles where customer_id like 'seed-%';  -- cascade: oy/foto/begeni/yorum/bekleme

-- ===== KULLANICILAR (95 Turk hesabi) =====
on conflict (customer_id) do nothing;

-- ===== ANILAR (402 foto: 241 genel + 161 Wikimedia gercek ornek) =====

-- ===== OYLAR (camera_votes) =====

